css:
.bk-gohan3 .meta{background:#fbf1e6;border-radius:3px;padding:1.5mm 2.5mm;font-size:0.909em;margin:0 0 3mm;color:#6b4a2e}
.bk-gohan3 table.ing td{padding:.9mm 1.5mm}
.bk-gohan3 table.ing td:last-child{text-align:right;white-space:nowrap}
.bk-gohan3 ol.steps{margin:0 0 3mm;padding-left:5mm}
.bk-gohan3 ol.steps li{margin:0 0 1.6mm}
.bk-gohan3 .say{display:flex;gap:2.5mm;align-items:flex-start;background:#fff6dd;border:1px solid #e8cf86;border-radius:3px;padding:2mm 2.5mm;margin:3mm 0;font-size:0.909em}
.bk-gohan3 .say svg.face{width:13mm;height:auto;flex:none;border-radius:2mm}
.bk-gohan3 .side{font-size:0.909em;color:#555;border-top:1px dotted #ccc;padding-top:1.5mm}
.bk-gohan3 .day{border:1px solid #e3d3c0;border-radius:3px;padding:2mm 2.5mm;margin:0 0 2.5mm}
.bk-gohan3 .day b.d{color:var(--c)}
